	ret = EventSetFree(set)
	if ret != SUCCESS {
		t.Errorf("EventSetFree: %v", ret)
	} else {
		t.Logf("EventSetFree: %v", ret)
	}

	set, _ = EventSetCreate()
	ret = set.Free()
	if ret != SUCCESS {
		t.Errorf("EventSet.Free: %v", ret)
	} else {
		t.Logf("EventSet.Free: %v", ret)
	}
}

